"""Writes frameworks/base/libs/hwui/Android.mk for this tree's build system
from hwui's Android.bp: libhwui for the host (glibc), with Skia and minikin
inside it, without the parts that need Android's graphics stack or system
services (listed below)."""

import sys

import bp

hwui = sys.argv[1]
skia = sys.argv[2]
parsed = bp.read(f"{hwui}/Android.bp")
defaults = bp.module(parsed, "libhwui_defaults")
hwui_defaults = bp.module(parsed, "hwui_defaults")

# SurfaceTexture is libgui's buffer queue; graphics stats go to a system
# service as protobuf; HWUIProperties is generated by sysprop (Mead's
# stand-in is frameworks/mead/hwui/HWUIProperties.sysprop.h, beside
# statslog.h's).
left_out = (
    "surfacetexture/",
    "service/GraphicsStatsService.cpp",
    "protos/",
    "HWUIProperties.sysprop",
)
srcs = [s for s in defaults["srcs"] if not s.startswith(left_out)]
# The shader cache's file, from Android 10's EGL loader, which Android links
# hwui to statically.
srcs += [
    "../../../native/opengl/libs/EGL/BlobCache.cpp",
    "../../../native/opengl/libs/EGL/FileBlobCache.cpp",
]
includes = hwui_defaults["include_dirs"]

# hwui's headers include Skia's and minikin's, which are inside it, so what
# links hwui (the graphics JNI) gets their include directories from it, as
# gen_skia_mk.py lists Skia's.
libskia = bp.module(bp.read(f"{skia}/Android.bp"), "libskia")
skia_includes = [f"{skia}/{d.rstrip('/')}" for d in
                 libskia["local_include_dirs"] + libskia["target"]["android"]["local_include_dirs"]
                 if d != "include/config/android"]
skia_includes += [f"{skia}/include/config/mead", f"{skia}/include/third_party/vulkan"]
exported = ["$(LOCAL_PATH)"] + skia_includes + ["frameworks/minikin/include", "/usr/include/harfbuzz"]
cflags = [f for f in hwui_defaults["cflags"] + defaults.get("cflags", [])
          if f not in ("-Werror", "-fvisibility=hidden")]
# hwui's symbols stay visible, for the graphics JNI in libandroid_runtime,
# which Android builds with hwui's sources it uses.


def listing(name, items):
    return f"{name} := \\\n" + " \\\n".join(f"    {item}" for item in items) + "\n"


print(f"""# Generated from Android.bp by frameworks/mead/tools/gen_hwui_mk.py; edit that instead.
#
# Android 10's libhwui for the host (glibc): Canvas, Bitmap, Paint, text
# through minikin, and the Skia pipelines, with Skia and minikin inside it.

LOCAL_PATH := $(call my-dir)

{listing("hwui_srcs", srcs)}
{listing("hwui_cflags", [f.replace('"', '\\"') for f in cflags])}
include $(CLEAR_VARS)
LOCAL_MODULE := libhwui
LOCAL_MODULE_TAGS := optional
LOCAL_SRC_FILES := $(hwui_srcs)
LOCAL_C_INCLUDES := \\
    $(LOCAL_PATH) \\
{"".join(f"    {d} \\{chr(10)}" for d in includes)}    frameworks/native/opengl/libs/EGL \\
    frameworks/native/include \\
    system/core/libsync/include \\
    frameworks/mead/hwui \\
    frameworks/mead/compat/include
LOCAL_EXPORT_C_INCLUDE_DIRS := \\
{"".join(f"    {d} \\{chr(10)}" for d in exported[:-1])}    {exported[-1]}
# Without TextureView's SurfaceTexture (see DeferredLayerUpdater.h).
LOCAL_CFLAGS := $(hwui_cflags) -fPIC -DSK_BUILD_FOR_ANDROID -DHWUI_NO_SURFACE_TEXTURE \\
    -DENABLE_STRING8_OBSOLETE_METHODS -DENABLE_STRING16_OBSOLETE_METHODS \\
    -include mead/android10_compat.h
LOCAL_CPPFLAGS := -std=gnu++17
LOCAL_WHOLE_STATIC_LIBRARIES := libskia libskia_cc libjpeg_static libminikin libmead_egl_extensions
LOCAL_SHARED_LIBRARIES := libandroidfw libbase libbinder libcutils libgui liblog libnativehelper \\
    libnativewindow libui libutils libziparchive
LOCAL_LDLIBS := -lEGL -lGLESv2 -l:libvulkan.so.1 -lcrypto -lfreetype -lharfbuzz -lpng16 -lwebp -lwebpmux -lwebpdemux -lexpat -lz -licuuc -licui18n -lpthread -ldl
LOCAL_ADDITIONAL_DEPENDENCIES := $(LOCAL_PATH)/Android.mk
LOCAL_MULTILIB := both
include $(BUILD_HOST_SHARED_LIBRARY)
""")
